(function(){
  if (window.__wireFieldInstalled__) return;
  window.__wireFieldInstalled__ = true;
  var canvas = document.getElementById('cv');
  var ctx = canvas.getContext('2d');
  var iSlider = document.getElementById('iSlider');
  var iVal = document.getElementById('iVal');
  var out = document.getElementById('out');
  var playBtn = document.getElementById('playBtn');
  var WX = 130, WY = 180, angle = 0, running = true;
  window.simState = { I: 5, B2: 50, B5: 20, running: true };
  function muT(I, dM) { return (2e-7 * I / (dM / 100)) * 1e6; }
  function draw(){
    var I = parseFloat(iSlider.value);
    var B2 = muT(I, 2), B5 = muT(I, 5);
    window.simState.I = I; window.simState.B2 = B2; window.simState.B5 = B5;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1; ctx.strokeRect(0.5, 0.5, canvas.width - 1, canvas.height - 1);
    ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 1;
    for (var gx = 0; gx <= canvas.width; gx += 40) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, canvas.height); ctx.stroke(); }
    for (var gy = 0; gy <= canvas.height; gy += 40) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(canvas.width, gy); ctx.stroke(); }
    var radii = [40, 72, 104, 136, 164];
    for (var r = 0; r < radii.length; r++) {
      var R = radii[r];
      ctx.strokeStyle = '#0369a1'; ctx.lineWidth = 1.5;
      ctx.beginPath(); ctx.arc(WX, WY, R, 0, Math.PI * 2); ctx.stroke();
      var n = Math.max(4, Math.round(R / 22));
      for (var k = 0; k < n; k++) {
        var a = (k / n) * Math.PI * 2 + angle;
        var hx = WX + R * Math.cos(a), hy = WY + R * Math.sin(a);
        var sx = WX + R * Math.cos(a + 0.22), sy = WY + R * Math.sin(a + 0.22);
        var ex = WX + R * Math.cos(a - 0.22), ey = WY + R * Math.sin(a - 0.22);
        ctx.strokeStyle = '#b91c1c'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(hx, hy); ctx.lineTo(ex, ey); ctx.stroke();
      }
    }
    ctx.fillStyle = '#0f172a';
    ctx.beginPath(); ctx.arc(WX, WY, 14, 0, Math.PI * 2); ctx.fill();
    ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(WX, WY, 6, 0, Math.PI * 2); ctx.stroke();
    ctx.fillStyle = '#fff'; ctx.font = 'bold 14px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('I', WX, WY + 4);
    ctx.font = '12px sans-serif'; ctx.fillStyle = '#0f172a'; ctx.textAlign = 'right';
    ctx.fillText('التيار يخرج من المستوي (نحو المشاهد)', canvas.width - 12, 20);
    ctx.fillText('خطوط الحقل حلقات دائرية مركزها السلك - الاتجاه: قاعدة اليد اليمنى', canvas.width - 12, 36);
    iVal.textContent = I.toFixed(1);
    out.textContent = 'I = ' + I.toFixed(1) + ' A | B(d = 2 cm) = ' + B2.toFixed(1) + ' µT | B(d = 5 cm) = ' + B5.toFixed(1) + ' µT';
    window.simState.time = (window.simState.time || 0) + 0.05;
  }
  function loop(){ if (running) angle += 0.03; draw(); requestAnimationFrame(loop); }
  playBtn.addEventListener('click', function(){ running = !running; window.simState.running = running; playBtn.textContent = running ? 'إيقاف الدوران' : 'تشغيل الدوران'; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
